head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function(target, type, options) {
    scwin.simulateWrapper('.w2floatingLayer_dragArea:last', 'drag-n-drop', {
        dx: 300,
        dy: 0
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 브라우저에서 columnMove 를 한다.
    //2. Do columnMove in the browser.
    //Verify step 2. A tooltip is created. (Tooltips are not created in previous versions)
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#floatingLayer2').css('left') == '500px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 24-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
